// ---- společné pomocné funkce (stejné ve všech workflowech) ----
const env = (k, d = '') => { const v = $env[k]; return (v === undefined || v === null || v === '') ? d : String(v); };
const clean = (items) => (items || []).map(i => (i && i.json !== undefined) ? i.json : i)
  .filter(j => j && typeof j === 'object' && Object.values(j).some(v => v !== '' && v !== null && v !== undefined));
const blockedCountries = () => { const s = new Set(env('BLOCKED_COUNTRIES', 'CR').split(',').map(x => x.trim().toUpperCase()).filter(Boolean)); s.add('CR'); return s; };
const domainOf = (e) => { const m = String(e || '').toLowerCase().match(/@([a-z0-9.-]+)/); return m ? m[1] : ''; };
const domainOfUrl = (u) => { try { if (!u) return ''; const h = new URL(/^https?:\/\//i.test(u) ? u : 'http://' + u).hostname.toLowerCase(); return h.replace(/^www\./, ''); } catch (e) { return ''; } };
const FREE_MAIL = new Set(['gmail.com','googlemail.com','seznam.cz','email.cz','centrum.cz','volny.cz','atlas.cz','post.cz','tiscali.cz','yahoo.com','yahoo.co.uk','yahoo.ca','yahoo.com.au','hotmail.com','hotmail.co.uk','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','mail.com','gmx.com','gmx.de','web.de','bigpond.com','shaw.ca','telus.net','rogers.com','comcast.net','att.net','verizon.net','btinternet.com','sky.com','virginmedia.com']);
const parseISO = (s) => { if (!s) return null; const d = DateTime.fromISO(String(s)); return d.isValid ? d : null; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const self = new Set([env('SENDER_EMAIL', 'kontakt@krystofkoci.com'), env('OWNER_EMAIL', '')].map(s => s.toLowerCase()).filter(Boolean));
const addr = (v) => { if (!v) return ''; if (typeof v === 'string') { const mm = v.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/); return mm ? mm[0].toLowerCase() : ''; }
  if (v.value && v.value[0]) return String(v.value[0].address || '').toLowerCase(); if (v.text) return addr(v.text); return ''; };
const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  const fromEmail = addr(m.from || m.From);
  const fromName = (m.from && m.from.value && m.from.value[0] && m.from.value[0].name) || '';
  const subject = String(m.subject || m.Subject || '');
  const headers = m.headers || {};
  const hget = (k) => { const v = headers[k] ?? headers[k.toLowerCase()]; if (!v) return ''; const s = Array.isArray(v) ? v.join(' ') : String(v); return s.replace(new RegExp('^' + k + ':\\s*', 'i'), '').trim(); };
  let text = String(m.text || '');
  if (!text && m.html) text = String(m.html).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (!text && m.snippet) text = String(m.snippet);
  text = text.split(/\r?\n(?:On .{5,120}wrote:|Dne .{5,120}napsal|-----Original Message-----|_{10,}|From: .+)\s*$/m)[0];
  text = text.split(/\r?\n>\s?/)[0].trim().slice(0, 4000);
  const autoSubmitted = hget('Auto-Submitted'); const precedence = hget('Precedence').toLowerCase();
  const isBounce = /mailer-daemon|postmaster/i.test(fromEmail) || /delivery status notification|undeliver|mail delivery failed|returned mail|nedoručiteln|delivery failure|delivery incomplete/i.test(subject);
  const isAutoReply = (!!autoSubmitted && !/^no$/i.test(autoSubmitted)) || !!hget('X-Autoreply') || !!hget('X-Autorespond') || /^(bulk|auto_reply|junk)$/.test(precedence)
    || /out of (the )?office|automatic reply|automatická odpověď|mimo kancelář|auto(-| )?reply|nepřítomnost|dovolen|vacation|away from/i.test(subject);
  const bouncedAddr = isBounce ? ((text.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g) || []).map(s => s.toLowerCase()).find(a => !self.has(a) && !/mailer-daemon|postmaster/.test(a)) || '') : '';
  const refs = m.references ? [].concat(m.references).join(' ') : hget('References');
  out.push({ json: { channel: 'email', gmail_id: m.id, thread_id: m.threadId || '', from_email: fromEmail, from_name: fromName, wa_from: '', subject, text,
    message_id_header: m.messageId || hget('Message-ID') || '', references: refs, is_self: self.has(fromEmail), is_bounce: isBounce,
    is_auto_reply: isAutoReply, bounced_addr: bouncedAddr, received_at: DateTime.now().toISO() } });
}
return out.filter(o => !o.json.is_self && (o.json.from_email || o.json.is_bounce));

// ---- společné pomocné funkce (stejné ve všech workflowech) ----
