const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const msgs = $('Agregace zpráv').first().json.data || [];
const leads = clean($input.all());
const byEmail = (e) => leads.filter(l => String(l.email || '').toLowerCase() === e).sort((a, b) => String(b.sent_1_at || '').localeCompare(String(a.sent_1_at || '')))[0];
const out = [];
for (const m of msgs) {
  const dom = domainOf(m.from_email);
  let lead = m.thread_id ? leads.find(l => l.thread_id && l.thread_id === m.thread_id) : null;
  if (!lead && m.is_bounce && m.bounced_addr) lead = byEmail(m.bounced_addr);
  if (!lead && m.from_email) lead = byEmail(m.from_email);
  if (!lead && dom && !FREE_MAIL.has(dom)) lead = leads.filter(l => domainOf(l.email) === dom && l.sent_1_at).sort((a, b) => String(b.sent_1_at || '').localeCompare(String(a.sent_1_at || '')))[0];
  if (!lead) { console.log('zpráva bez leadu: ' + m.from_email + ' / ' + m.subject); continue; }
  const expectedOwn = (lead.sent_1_at ? 1 : 0) + (lead.sent_2_at ? 1 : 0) + (lead.sent_3_at ? 1 : 0) + (Number(lead.auto_reply_count) || 0);
  out.push({ json: { ...m, lead, lead_id: lead.id, expected_own_messages: expectedOwn, thread_id: m.thread_id || lead.thread_id || '' } });
}
return out;

