const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const m = $('Spárovat s leadem').item.json;
const t = $input.item.json || {};
const sender = env('SENDER_EMAIL', 'kontakt@krystofkoci.com').toLowerCase();
let ownCount = 0;
for (const msg of (t.messages || [])) {
  const hdrs = ((msg.payload || {}).headers || []);
  const from = String((hdrs.find(h => String(h.name).toLowerCase() === 'from') || {}).value || '').toLowerCase();
  if (from.includes(sender)) ownCount++;
}
// ruční převzetí = ve vlákně je víc zpráv od tebe, než kolik jich poslal systém
const manual = truthy(m.lead.manual_takeover) || (ownCount > 0 && ownCount > m.expected_own_messages);
let route = 'classify';
if (m.is_bounce) route = 'bounce'; else if (m.is_auto_reply) route = 'auto'; else if (manual) route = 'manual';
// historie vlákna pro schvalovací e-mail (Gmail metadata: odesílatel, čas, úryvek)
const history = (t.messages || []).map(msg => {
  const hdrs = ((msg.payload || {}).headers || []);
  const from = String((hdrs.find(h => String(h.name).toLowerCase() === 'from') || {}).value || '');
  const at = msg.internalDate ? DateTime.fromMillis(Number(msg.internalDate)).setZone(env('OWNER_TZ', 'Europe/Prague')).toFormat('d.L. HH:mm') : '';
  return { from, at, mine: from.toLowerCase().includes(sender), snippet: String(msg.snippet || '').slice(0, 400) };
}).slice(-8);
return { json: { ...m, route, history } };

const q = ($input.first().json || {}).query || {};
const expected = String($env.WHATSAPP_VERIFY_TOKEN || '');
const ok = q['hub.mode'] === 'subscribe' && !!expected && String(q['hub.verify_token'] || '') === expected;
return [{ json: { ok, challenge: String(q['hub.challenge'] || '') } }];

