const digits = (s) => String(s || '').replace(/\D/g, '');
const samePhone = (a, b) => { const x = digits(a), y = digits(b); return x.length >= 8 && y.length >= 8 && x.slice(-9) === y.slice(-9); };

const crypto = require('crypto');
const item = $input.first();
const j = item.json || {};
const secret = env('WHATSAPP_APP_SECRET', '');
if (secret) {
  const sig = String((j.headers || {})['x-hub-signature-256'] || '').replace(/^sha256=/, '');
  let raw = '';
  try { const B = (typeof Buffer !== 'undefined') ? Buffer : require('buffer').Buffer; raw = item.binary && item.binary.data ? B.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(j.body || {}); } catch (e) { raw = ''; }
  const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  if (!sig || sig !== expected) { console.log('WhatsApp: neplatný podpis – zpráva zahozena'); return []; }
}
const owner = digits(env('OWNER_WHATSAPP', ''));
const out = [];
for (const e of ((j.body || {}).entry || [])) for (const c of (e.changes || [])) {
  const v = c.value || {};
  const names = Object.fromEntries((v.contacts || []).map(x => [String(x.wa_id), (x.profile && x.profile.name) || '']));
  for (const m of (v.messages || [])) {
    const from = digits(m.from);
    if (!from || (owner && from === owner)) continue;
    let text = '';
    if (m.type === 'text') text = (m.text && m.text.body) || '';
    else if (m.type === 'button') text = (m.button && m.button.text) || '';
    else if (m.type === 'interactive') text = JSON.stringify(m.interactive).slice(0, 300);
    else text = `[klient poslal ${m.type} – zobraz ve WhatsApp Manageru]`;
    out.push({ channel: 'whatsapp', wa_from: from, wa_message_id: m.id, from_name: names[from] || '', from_email: '', text: String(text).slice(0, 4000),
      subject: 'WhatsApp', thread_id: '', message_id_header: '', references: '', received_at: DateTime.now().toISO() });
  }
}
if (!out.length) return [];
return [{ json: { messages: out } }];

