const digits = (s) => String(s || '').replace(/\D/g, '');
const samePhone = (a, b) => { const x = digits(a), y = digits(b); return x.length >= 8 && y.length >= 8 && x.slice(-9) === y.slice(-9); };

let c = $input.item.json; c = c.output ?? c.text ?? c.response ?? c;
if (typeof c === 'string') { try { c = JSON.parse(c.replace(/^```json|```$/g, '').trim()); } catch (e) { c = { intent: 'other', language: '', summary_cs: c.slice(0, 200) }; } }
const m = $('Sjednotit').item.json;
const lead = m.lead;
let intent = String(c.intent || 'other');
if (c.complaint) intent = intent === 'unsubscribe' ? 'unsubscribe' : 'complaint';
const langRaw = String(c.language || '').toLowerCase();
const language = langRaw.startsWith('cs') || langRaw.startsWith('cz') ? 'cs' : (langRaw.startsWith('en') ? 'en' : (lead.lang === 'cs' ? 'cs' : 'en'));
const statusMap = { interested: 'interested', question: 'replied', price: 'negotiating', other: 'replied', not_interested: 'lost', unsubscribe: 'unsubscribed', complaint: 'do_not_contact', out_of_office: lead.status };
const frozen = ['won', 'do_not_contact', 'unsubscribed', 'bounced'].includes(String(lead.status));
let status = frozen ? lead.status : (statusMap[intent] || 'replied');
if (!frozen && c.order) status = 'negotiating';
const autoCount = Number(lead.auto_reply_count) || 0;
const paused = truthy(lead.manual_takeover) || String(lead.next_action || '') === 'owner';
// každá odpověď jde nejdřív tobě ke schválení → bez limitu automatických odpovědí
const draftable = ['interested', 'question', 'price', 'other', 'complaint'].includes(intent) || !!c.order || !!c.wants_call;
let should_reply = draftable && !paused && !['unsubscribed', 'bounced'].includes(String(lead.status));
let escalate_reason = '';
if (intent === 'complaint' && !should_reply) escalate_reason = 'stížnost / citlivá reakce – odpověz sám (status do_not_contact)';
if (paused && draftable) escalate_reason = escalate_reason || 'vlákno čeká na tebe (next_action=owner nebo ruční převzetí)';
// WhatsApp: klient napsal první → opt-in; nebo v e-mailu sám požádal o WhatsApp a uvedl číslo
let whatsapp = lead.whatsapp || '', optIn = truthy(lead.whatsapp_opt_in);
const extra = [];
if (m.channel === 'whatsapp') { whatsapp = '+' + digits(m.wa_from); optIn = true; }
else if (c.wants_whatsapp && digits(c.whatsapp_number).length >= 8) { whatsapp = '+' + digits(c.whatsapp_number); optIn = true;
  extra.push(`klient chce pokračovat přes WhatsApp (${whatsapp}) – první zprávu mimo 24h okno mu pošli ty z WhatsApp Manageru; jakmile odpoví, převezme to agent`); }
const date = DateTime.now().toFormat('d.L.');
