  next_action: escalate_reason ? 'owner' : (lead.next_action || '') };
const icon = { interested: '🟢', question: '🔵', price: '💰', not_interested: '⚪', unsubscribe: '🚫', complaint: '🔴', other: '💬', out_of_office: '🏖' }[intent] || '💬';
const owner_subject = `${icon} ${m.channel === 'whatsapp' ? 'WhatsApp' : 'Odpověď'}: ${lead.name} (${intent})`;
const owner_html = `<p><b>${esc(lead.name)}</b> (${esc(lead.city)}, ${esc(lead.country)}) · ${esc(intent)} · kanál ${esc(m.channel)}</p>` +
  `<p>Od: ${esc(m.from_name)} ${esc(m.from_email)} ${m.wa_from ? '+' + esc(m.wa_from) : ''}</p><p><i>${esc(summary)}</i></p>` +
  `<blockquote style="border-left:3px solid #ccc;padding-left:10px">${esc(String(m.text || '').slice(0, 2000)).replace(/\n/g, '<br>')}</blockquote>` +
  `<p>Náhled: ${esc(lead.preview_url || '-')}</p>` +
  `<p>${escalate_reason ? '⚠️ ' + esc(escalate_reason) : 'Bez odpovědi (nemá zájem / odhlášení / nepřítomnost).'}</p>` +

  (extra.length ? '<p>📱 ' + esc(extra.join('; ')) + '</p>' : '') + `<p>ID: <code>${esc(lead.id)}</code></p>`;
