// ---- sestavení MIME zprávy pro Gmail API (raw, base64url) ----
function buildMime(o) {
  const B = (typeof Buffer !== 'undefined') ? Buffer : require('buffer').Buffer;
  const encW = (s) => /[^\x00-\x7F]/.test(s) ? '=?UTF-8?B?' + B.from(s, 'utf8').toString('base64') + '?=' : s;
  const b64 = (s) => B.from(s, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
  const boundary = 'np_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  const head = [`From: ${encW(o.fromName)} <${o.fromEmail}>`, `To: ${o.to}`, `Subject: ${encW(o.subject)}`, 'MIME-Version: 1.0'];
  if (o.inReplyTo) head.push(`In-Reply-To: ${o.inReplyTo}`);
  if (o.references) head.push(`References: ${o.references}`);
  if (o.unsubscribe) head.push(`List-Unsubscribe: <${o.unsubscribe}>`);
  head.push('X-Outreach-Bot: 1');
  head.push(`Content-Type: multipart/alternative; boundary="${boundary}"`);
  const parts = [`--${boundary}`, 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', b64(o.text || ''),
                 `--${boundary}`, 'Content-Type: text/html; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', b64(o.html || ''), `--${boundary}--`, ''];
  const msg = head.join('\r\n') + '\r\n\r\n' + parts.join('\r\n');
  return B.from(msg, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
